+    await deletePoller.pollUntilDone();
+    console.log(`Soft-deleted "${secretName}".`);
+
+    await client.purgeDeletedSecret(secretName);
+    console.log(`Purged "${secretName}".`);
+  } catch (error: unknown) {
+    console.error(`Key Vault operation failed: ${describeError(error)}`);
+    throw error;
+  }
+}
+
+main().catch(() => {
+  process.exitCode = 1;
+});
+



